from typing import TYPE_CHECKING from vllm.distributed import (    get_tensor_model_parallel_rank,    get_tensor_model_parallel_world_size,)from vllm.distributed.kv_transfer.kv_connector.v1.multi_connector import MultiConnectorfrom vllm_ascend.distributed.kv_transfer.ascend_multi_connector import AscendMultiConnectorfrom vllm_ascend.distributed.kv_transfer.kv_p2p.mooncake_layerwise_connector import MooncakeLayerwiseConnectorfrom vllm_custom_plugins.plugins.zero_interrupt.vllm_ascend.utils import asymmetric_divide from vllm.config import VllmConfigif TYPE_CHECKING:    from vllm.config import VllmConfig    from vllm.distributed.kv_transfer.kv_connector.v1.base import KVConnectorRole    from vllm.v1.core.kv_cache_manager import KVCacheBlocks    from vllm.v1.kv_cache_interface import KVCacheConfig    from vllm.v1.request import Request  class PatchAscendMultiConnector(AscendMultiConnector):    def __init__(        self,        vllm_config: "VllmConfig",        role: "KVConnectorRole",        kv_cache_config: "KVCacheConfig | None" = None,    ):                  super().__init__(vllm_config, role, kv_cache_config)         # [h30014172] 非对称 TP 信息        tp_size = get_tensor_model_parallel_world_size()        tp_rank = get_tensor_model_parallel_rank()         total_num_kv_heads = vllm_config.model_config.hf_text_config.num_key_value_heads        uneven_split = (total_num_kv_heads % tp_size != 0)        if uneven_split:            self.local_kv_heads, self.kv_head_offset = asymmetric_divide(                total_num_kv_heads, tp_size, tp_rank            )        else:            self.local_kv_heads = total_num_kv_heads // tp_size            self.kv_head_offset = tp_rank * self.local_kv_heads        self.total_num_kv_heads = total_num_kv_heads        self.tp_size = tp_size        self.tp_rank = tp_rank     def update_state_after_alloc(self, request: "Request", blocks: "KVCacheBlocks", num_external_tokens: int):        chosen_connector = self._requests_to_connector.get(request.request_id, -1)        empty_blocks = blocks.new_empty()        for i, c in enumerate(self._connectors):            if i == chosen_connector or isinstance(c, MooncakeLayerwiseConnector):                c.update_state_after_alloc(request, blocks, num_external_tokens)            else:                c.update_state_after_alloc(request, empty_blocks, 0)     # ========== [h30014172] 新增：非对称 TP 信息注入 ==========    def register_kv_caches(self, kv_caches):        super().register_kv_caches(kv_caches)        # 将非对称信息注入到子 connector        if self.uneven_split:            for connector in self._connectors:                if hasattr(connector, 'connector_worker') and connector.connector_worker is not None:                    worker = connector.connector_worker                    worker.uneven_split = self.uneven_split                    worker.local_kv_heads = self.local_kv_heads                    worker.kv_head_offset = self.kv_head_offset                    worker.total_num_kv_heads = self.total_num_kv_heads                    worker.tp_size = self.tp_size                    worker.tp_rank = self.tp_rank     # ========== [h30014172] 新增：KV 传输映射计算 ==========    @staticmethod    def compute_kv_transfer_mapping(        total_num_kv_heads: int,        tp_size: int,        dst_rank: int,        uneven_split: bool = False,    ) -> list[tuple[int, int, int, int]]:        """计算非对称 TP 下 KV 传输的地址映射。         Args:            total_num_kv_heads: 全局 kv heads 总数            tp_size: TP 并行度            dst_rank: 目标 rank（D 侧）            uneven_split: 是否非对称切分         Returns:            List of (src_rank, src_local_offset, dst_local_offset, num_heads)        """        if not uneven_split:            dst_kv_heads = total_num_kv_heads // tp_size            return [(dst_rank, 0, 0, dst_kv_heads)]         dst_kv_heads, dst_global_offset = asymmetric_divide(            total_num_kv_heads, tp_size, dst_rank        )         mapping = []        remaining = dst_kv_heads        dst_local_offset = 0         for src_rank in range(tp_size):            if remaining <= 0:                break            src_kv_heads, src_global_offset = asymmetric_divide(                total_num_kv_heads, tp_size, src_rank            )            overlap_start = max(dst_global_offset, src_global_offset)            overlap_end = min(                dst_global_offset + dst_kv_heads,                src_global_offset + src_kv_heads,            )            if overlap_start >= overlap_end:                continue             transfer_heads = overlap_end - overlap_start            src_local_offset = overlap_start - src_global_offset            mapping.append(                (src_rank, src_local_offset, dst_local_offset, transfer_heads)            )            dst_local_offset += transfer_heads            remaining -= transfer_heads         assert remaining == 0, (            f"Mapping incomplete: {remaining} heads unmapped for dst_rank={dst_rank}"        )        return mapping